// Sprint 0 stub: validate payload + echo back a deterministic reply.
// Sprint 2 will replace this with: RAG search -> LLM call -> grounded reply.

const body = $json.body || $json;
const sessionId = body.session_id || 'no-session';
const userMessage = body.message || '';
const language = body.language || 'en';

const stub = language === 'fr'
  ? `Bonjour ! C'est une réponse provisoire (Sprint 0). Votre message : "${userMessage}".`
  : `Hi! This is a Sprint 0 stub reply. Your message: "${userMessage}".`;

return [{
  json: {
    session_id: sessionId,
    language,
    reply: stub,
    prompt_version: 'stub-0.1',
    timestamp: new Date().toISOString()
  }
}];
